:root{--bg:#0f1720;--panel:#17212c;--line:#263444;--text:#e8eef5;--mute:#8fa1b3;--accent:#4aa3ff;--good:#3ecf8e;--bad:#ff7a6b}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
.wrap{max-width:1120px;margin:0 auto;padding:48px 32px 40px}
header{margin-bottom:36px;padding-bottom:20px;border-bottom:1px solid var(--line)}
h1{margin:0;font-size:44px;font-weight:750;letter-spacing:-.02em;line-height:1.1}
.sub{margin:8px 0 0;font-size:18px;color:var(--mute);letter-spacing:.04em;text-transform:uppercase}
h2{margin:0 0 16px;font-size:13px;font-weight:650;letter-spacing:.12em;text-transform:uppercase;color:var(--mute)}
section{margin-bottom:40px}
.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.tile{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:20px 22px}
.tile .lbl{font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--mute)}
.tile .val{margin:10px 0 8px;font-size:40px;font-weight:700;line-height:1;font-variant-numeric:tabular-nums}
.tile .chg{font-size:15px;font-weight:600;font-variant-numeric:tabular-nums}
.tile .chg small{color:var(--mute);font-weight:400;margin-left:6px}
.good{color:var(--good)}.bad{color:var(--bad)}
table{width:100%;border-collapse:collapse;background:var(--panel);border:1px solid var(--line);border-radius:10px;overflow:hidden;font-variant-numeric:tabular-nums}
th,td{padding:11px 22px;text-align:right;border-bottom:1px solid var(--line)}
th:first-child,td:first-child{text-align:left}
th{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute);font-weight:600;background:#1b2734}
td{font-size:17px}
td:first-child{font-weight:600}
tbody tr:last-child td{border-bottom:0}
tbody tr:nth-child(even){background:rgba(255,255,255,.02)}
.bars{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px 22px}
.row{display:grid;grid-template-columns:120px 1fr 90px;align-items:center;gap:16px;padding:10px 0}
.row .n{font-weight:600}
.track{height:18px;background:#1f2c3a;border-radius:4px}
.fill{height:100%;background:linear-gradient(90deg,#2b7fd6,var(--accent));border-radius:4px}
.row .c{text-align:right;font-variant-numeric:tabular-nums;color:var(--mute)}
footer{padding-top:20px;border-top:1px solid var(--line);color:var(--mute);font-size:14px}
@media(max-width:860px){.tiles{grid-template-columns:repeat(2,1fr)}}
@media(max-width:480px){.tiles{grid-template-columns:1fr}.wrap{padding:28px 16px}th,td{padding:10px 12px}}

